#define CHECK(x) do {if(!(x)){fprintf(stderr,"line %d: %s\n",__LINE__,#x);fflush(nullptr);ExitProcess(1);}}while(0)
namespace fs=std::filesystem;
static constexpr unsigned Frames=16;
static std::string directory,pluginPath,role="relay";
static std::string path(const char*n){return (fs::path(directory)/n).string();}
static uint64_t timeAt(unsigned n){return gst_util_uint64_scale(n,GST_SECOND,30);}
static uint64_t pixelHash(const unsigned char*data,size_t stride){uint64_t hash=14695981039346656037ULL;for(unsigned y=0;y<32;++y)for(unsigned x=0;x<256;++x){hash^=data[y*stride+x];hash*=1099511628211ULL;}return hash;}
static HANDLE event(const char*n,bool manual=true){uint64_t hash=14695981039346656037ULL;for(unsigned char c:directory){hash^=c;hash*=1099511628211ULL;}auto name="Local\\FLDecoder-"+std::to_string(hash)+"-"+n;auto h=CreateEventA(nullptr,manual,FALSE,name.c_str());CHECK(h);return h;}
static void wait(HANDLE h){CHECK(WaitForSingleObject(h,10000)==WAIT_OBJECT_0);}
static void terminal(GstElement*p){auto*b=gst_element_get_bus(p);auto*m=gst_bus_timed_pop_filtered(b,10*GST_SECOND,GstMessageType(GST_MESSAGE_EOS|GST_MESSAGE_ERROR));CHECK(m&&GST_MESSAGE_TYPE(m)==GST_MESSAGE_EOS);gst_message_unref(m);gst_object_unref(b);}
static flSessionCapabilities caps(){flSessionCapabilities c{};c.version=2;c.videoCount=c.audioCount=1;c.video[0]={FL_FORMAT_RGBA8,64,32,30,1};c.audio[0]={FL_PCM_S16,48000,2};return c;}
static GstFrameLinkMemoryPolicy policy(){GstFrameLinkMemoryPolicy p{};p.version=1;for(unsigned i=0;i<2;++i){flMemoryRequirementsInit(&p.requirements[i]);p.requirements[i].allowedResourceTypes=FL_MEMORY_D3D11;p.requirements[i].allowedOperations=0;p.requirements[i].requiredUsage=FL_MEMORY_GPU_SAMPLE;p.paths[i].version=1;p.paths[i].resourceType=FL_MEMORY_D3D11;p.paths[i].supportedUsage=FL_MEMORY_GPU_SAMPLE;}p.paths[0].supportedUsage=p.requirements[0].requiredUsage=FL_MEMORY_GPU_SAMPLE|FL_MEMORY_GPU_RENDER;return p;}
struct Audio {
 GstElement*pipe=nullptr,*port=nullptr;
 Audio(FlGstSession*s,bool producer,bool relayOutput=false){CHECK(fl_gst_session_register_track(s,FL_GST_TRACK_VIDEO)==FL_GST_SESSION_READY);flSessionConfig cfg{};CHECK(fl_gst_session_get_config(s,&cfg)==FL_GST_SESSION_READY);GError*e=nullptr;pipe=gst_parse_launch(producer?"appsrc name=port is-live=true format=time block=true max-buffers=2 max-bytes=0 caps=audio/x-raw,format=S16LE,layout=interleaved,rate=48000,channels=2,channel-mask=(bitmask)0x3 ! framelinkaudiosink tracks=av":"framelinkaudiosrc tracks=av ! appsink name=port max-buffers=1 sync=false async=false enable-last-sample=false",&e);CHECK(pipe&&!e);port=gst_bin_get_by_name(GST_BIN(pipe),"port");CHECK(port);if(relayOutput)g_object_set(port,"block",FALSE,nullptr);auto*c=fl_gst_session_create_context(s);gst_element_set_context(pipe,c);gst_context_unref(c);CHECK(fl_gst_session_track_ready(s,FL_GST_TRACK_VIDEO,cfg.generation)==FL_GST_SESSION_READY);}
 void start(){CHECK(gst_element_set_state(pipe,GST_STATE_PLAYING)!=GST_STATE_CHANGE_FAILURE);}
 ~Audio(){CHECK(gst_element_set_state(pipe,GST_STATE_NULL)!=GST_STATE_CHANGE_FAILURE);gst_object_unref(port);gst_object_unref(pipe);}
};
// Bytes are local-test evidence, not a new public wire protocol. Every field is
// independently checked by the final reader; PCM data does not originate at relay.
struct Decoded {uint64_t magic=0x464c4445434f4445ULL,identity=0,absolutePts=0,relativePts=0,duration=0,hash=0,decodedDts=GST_CLOCK_TIME_NONE;};
struct Decoder {
 GstElement*pipeline=nullptr,*sink=nullptr;GstD3D11Converter*converter=nullptr;
 GstClockTime origin=GST_CLOCK_TIME_NONE;std::vector<uint64_t> hashes;
 Decoded fill(GstBuffer*buffer,unsigned n){
  auto*mem=gst_buffer_peek_memory(buffer,0);auto*device=GST_D3D11_MEMORY_CAST(mem)->device;
  if(!pipeline){GError*e=nullptr;pipeline=gst_parse_launch("videotestsrc num-buffers=16 pattern=snow ! video/x-raw,format=NV12,width=320,height=240,framerate=30/1 ! x264enc tune=zerolatency speed-preset=ultrafast key-int-max=30 ! h264parse ! d3d11h264dec ! video/x-raw(memory:D3D11Memory),format=NV12 ! appsink name=decoded sync=false enable-last-sample=false max-buffers=1",&e);CHECK(pipeline&&!e);auto*c=gst_d3d11_context_new(device);gst_element_set_context(pipeline,c);gst_context_unref(c);sink=gst_bin_get_by_name(GST_BIN(pipeline),"decoded");CHECK(sink);CHECK(gst_element_set_state(pipeline,GST_STATE_PLAYING)!=GST_STATE_CHANGE_FAILURE);}
  auto*sample=gst_app_sink_try_pull_sample(GST_APP_SINK(sink),5*GST_SECOND);CHECK(sample);auto*input=gst_sample_get_buffer(sample);CHECK(gst_buffer_n_memory(input)==1);auto*memory=gst_buffer_peek_memory(input,0);CHECK(gst_is_d3d11_memory(memory)&&GST_D3D11_MEMORY_CAST(memory)->device==device);CHECK(!gst_mini_object_get_qdata(GST_MINI_OBJECT(memory),FrameLinkD3DProducer::key()));
  CHECK(GST_CLOCK_TIME_IS_VALID(GST_BUFFER_PTS(input))&&!GST_CLOCK_TIME_IS_VALID(GST_BUFFER_DTS(input)));if(!n)origin=GST_BUFFER_PTS(input);Decoded result;result.identity=n;result.absolutePts=GST_BUFFER_PTS(input);result.relativePts=result.absolutePts-origin;result.duration=GST_BUFFER_DURATION(input);result.decodedDts=GST_BUFFER_DTS(input);CHECK(result.relativePts==timeAt(n)&&result.duration==timeAt(1));
  if(!converter){GstVideoInfo in{},out{};CHECK(gst_video_info_from_caps(&in,gst_sample_get_caps(sample)));CHECK(GST_VIDEO_INFO_FORMAT(&in)==GST_VIDEO_FORMAT_NV12&&GST_VIDEO_INFO_WIDTH(&in)==320&&GST_VIDEO_INFO_HEIGHT(&in)==240);gst_video_info_set_format(&out,GST_VIDEO_FORMAT_RGBA,64,32);out.colorimetry.range=GST_VIDEO_COLOR_RANGE_0_255;converter=gst_d3d11_converter_new(device,&in,&out,nullptr);CHECK(converter);}
  CHECK(gst_d3d11_converter_convert_buffer(converter,input,buffer));auto*d=gst_d3d11_device_get_device_handle(device);auto*c=gst_d3d11_device_get_device_context_handle(device);D3D11_QUERY_DESC desc{D3D11_QUERY_EVENT,0};ID3D11Query*done=nullptr;CHECK(SUCCEEDED(d->CreateQuery(&desc,&done)));gst_d3d11_device_lock(device);c->End(done);c->Flush();HRESULT r;const auto deadline=g_get_monotonic_time()+2000000;do{r=c->GetData(done,nullptr,0,0);if(r==S_FALSE)g_usleep(100);}while(r==S_FALSE&&g_get_monotonic_time()<deadline);gst_d3d11_device_unlock(device);done->Release();CHECK(r==S_OK);
  // Only release decoder storage after the actual conversion GPU work finishes.
  gst_sample_unref(sample);auto*meta=gst_buffer_get_video_meta(buffer);GstMapInfo map{};CHECK(meta&&gst_memory_map(mem,&map,GST_MAP_READ));auto*data=map.data+meta->offset[0];for(unsigned y=0;y<32;++y)for(unsigned x=3;x<256;x+=4)CHECK(data[y*meta->stride[0]+x]==255);result.hash=pixelHash(data,meta->stride[0]);gst_memory_unmap(mem,&map);for(auto hash:hashes)CHECK(hash!=result.hash);hashes.push_back(result.hash);return result;
 }
 ~Decoder(){if(pipeline){CHECK(!gst_app_sink_try_pull_sample(GST_APP_SINK(sink),5*GST_SECOND));CHECK(gst_app_sink_is_eos(GST_APP_SINK(sink)));terminal(pipeline);CHECK(gst_element_set_state(pipeline,GST_STATE_NULL)!=GST_STATE_CHANGE_FAILURE);gst_object_unref(sink);gst_object_unref(pipeline);gst_object_unref(converter);}}
};
static std::ofstream rows(){std::ofstream f(path((role+".csv").c_str()));CHECK(f.good());f<<"identity,decoded_pts_ns,relative_pts_ns,duration_ns,hash,video_pts_ns,pcm_pts_ns,generation,metadata_version,metadata_flags,dts_ns,oracle_readback_bytes,mapped_video_pts_ns,decoded_dts_ns,converted_output_bytes\n";return f;}
static void record(std::ofstream&f,const Decoded&d,uint64_t pcmPts,uint64_t videoMapped,const flFrameMetadata&meta,uint64_t readbackBytes){f<<d.identity<<','<<d.absolutePts<<','<<d.relativePts<<','<<d.duration<<','<<d.hash<<','<<37000000+d.relativePts<<','<<pcmPts<<','<<meta.streamGeneration<<','<<meta.version<<','<<meta.flags<<','<<meta.dtsNs<<','<<readbackBytes<<','<<videoMapped<<','<<d.decodedDts<<','<<(role=="source"?8192:0)<<'\n';f.flush();CHECK(f.good());}
static void summary(const char*detail,bool held=false){std::ofstream f(path((role+".json").c_str()));CHECK(f.good());f<<"{\"video\":16,\"pcm_sample_frames\":25600,\"pcm_bytes\":102400,\"terminal\":true,\"detail\":\""<<detail<<"\",\"held_last_proof\":"<<(held?"true":"false")<<",\"same_allocation_checked\":"<<(role=="relay"?"true":"false")<<"}\n";}
static void source(){auto c=caps();auto p=policy();GstFrameLinkMemoryPolicy bound{};auto*s=fl_gst_session_new(3);flChannel*writer=nullptr;GError*e=nullptr;CHECK(fl_gst_session_open_local_native(s,TRUE,path("input").c_str(),&c,1,2,80,10000,10000,&p,&bound,&writer,nullptr,&e));flSessionConfig cfg{};CHECK(fl_gst_session_get_config(s,&cfg)==FL_GST_SESSION_READY);
 {Audio audio(s,true);audio.start();auto owner=std::make_shared<FrameLinkD3DProducer>(writer);CHECK(owner->valid());Decoder decoder;auto out=rows();auto retired=event("retired",false);CHECK(fl_gst_session_local_ready(s,TRUE,10000,nullptr));
 for(unsigned n=0;n<Frames;++n){auto*buffer=owner->acquire(5000);CHECK(buffer);const auto decoded=decoder.fill(buffer,n);flFrameMetadata meta{FL_FRAME_METADATA_VERSION,FL_FRAME_HAS_DURATION,0,decoded.duration,cfg.generation,{}};const auto pts=37000000+decoded.relativePts;CHECK(owner->submit(buffer,pts,&meta)==FL_OK);auto*pcm=gst_buffer_new_allocate(nullptr,6400,nullptr);CHECK(pcm);gst_buffer_memset(pcm,0,n+31,6400);CHECK(gst_buffer_fill(pcm,0,&decoded,sizeof decoded)==sizeof decoded);GST_BUFFER_PTS(pcm)=decoded.relativePts;GST_BUFFER_DURATION(pcm)=decoded.duration;CHECK(gst_app_src_push_buffer(GST_APP_SRC(audio.port),pcm)==GST_FLOW_OK);record(out,decoded,decoded.relativePts,pts,meta,8192);wait(retired);gst_buffer_unref(buffer);}
 FlGstVideoEvent end{FL_GST_VIDEO_END,Frames,37000000+timeAt(Frames-1),0};CHECK(fl_gst_session_send_video_event(s,cfg.generation,&end)==FL_GST_SESSION_READY);CHECK(fl_gst_session_video_eos(s,cfg.generation,Frames,end.ptsNs)==FL_GST_SESSION_READY);CHECK(gst_app_src_end_of_stream(GST_APP_SRC(audio.port))==GST_FLOW_OK);terminal(audio.pipe);CHECK(fl_gst_session_finish_local(s,TRUE,10000,nullptr));CloseHandle(retired);owner.reset();summary("actual decoder GPU conversion complete before storage release; source oracle readback explicit");}
 // FrameLinkD3DProducer owns/closes writer after its last reservation disappears.
 g_object_unref(s);
}
static void receiver(){auto c=caps();auto p=policy();GstFrameLinkMemoryPolicy bound{};auto*s=fl_gst_session_new(3);flChannel*reader=nullptr;GError*e=nullptr;CHECK(fl_gst_session_open_local_native_pool_receiver(s,path("output").c_str(),&c,1,2,80,10000,10000,&p,&bound,&reader,nullptr,&e));flSessionConfig cfg{};CHECK(fl_gst_session_get_config(s,&cfg)==FL_GST_SESSION_READY);
 {Audio audio(s,false);audio.start();auto out=rows();auto held=event("held"),release=event("release");std::vector<uint64_t> hashes;uint64_t origin=0;CHECK(fl_gst_session_local_ready(s,FALSE,10000,nullptr));
 for(unsigned n=0;n<Frames;++n){flFrame frame{};CHECK(flAcquireFrame(reader,&frame,5000)==FL_OK&&frame.ptsNs==int64_t(37000000+timeAt(n)));flFrameMetadata meta{};CHECK(flGetFrameMetadata(reader,&frame,&meta)==FL_OK&&meta.version==FL_FRAME_METADATA_VERSION&&meta.flags==FL_FRAME_HAS_DURATION&&meta.dtsNs==0&&meta.durationNs==timeAt(1)&&meta.streamGeneration==cfg.generation);auto*sample=gst_app_sink_try_pull_sample(GST_APP_SINK(audio.port),5*GST_SECOND);CHECK(sample);auto*pcm=gst_sample_get_buffer(sample);GstMapInfo map{};CHECK(gst_buffer_map(pcm,&map,GST_MAP_READ)&&map.size==6400);Decoded decoded{};memcpy(&decoded,map.data,sizeof decoded);CHECK(decoded.magic==Decoded{}.magic&&decoded.identity==n&&decoded.relativePts==timeAt(n)&&decoded.duration==meta.durationNs&&decoded.decodedDts==GST_CLOCK_TIME_NONE);if(!n)origin=decoded.absolutePts;CHECK(decoded.absolutePts>=origin&&decoded.absolutePts-origin==decoded.relativePts);for(size_t i=sizeof decoded;i<map.size;++i)CHECK(map.data[i]==uint8_t(n+31));gst_buffer_unmap(pcm,&map);gint64 videoMapped=0,audioMapped=0;CHECK(fl_gst_session_map_running_time(s,cfg.generation,frame.ptsNs,TRUE,&videoMapped)==FL_GST_SESSION_READY&&fl_gst_session_map_running_time(s,cfg.generation,decoded.relativePts,TRUE,&audioMapped)==FL_GST_SESSION_READY);CHECK(audioMapped>=0&&GST_BUFFER_PTS(pcm)==uint64_t(audioMapped)&&videoMapped-audioMapped==37000000&&GST_BUFFER_DURATION(pcm)==decoded.duration);const auto observedPcmPts=GST_BUFFER_PTS(pcm);gst_sample_unref(sample);
 uint64_t lease=0;CHECK(flLeaseFrame(reader,&frame,&lease)==FL_OK);auto verify=[&](flImage*image){flMappedImage pixels{};CHECK(flImageMapPlanes(image,&pixels)==FL_OK);CHECK(pixelHash(static_cast<unsigned char*>(pixels.plane[0].pixels),pixels.plane[0].stride)==decoded.hash);flImageUnmap(image);};verify(frame.image);for(auto h:hashes)CHECK(h!=decoded.hash);hashes.push_back(decoded.hash);
 if(n+1==Frames){CHECK(SetEvent(held));wait(release);flFrame retained{};uint64_t generation=0;CHECK(flReadLeaseFrame(reader,lease,&retained,&generation)==FL_OK&&retained.ptsNs==frame.ptsNs);verify(retained.image);}
 CHECK(flCompleteReadLease(reader,lease)==FL_OK&&flCollectReadLeases(reader)==FL_OK);record(out,decoded,observedPcmPts,uint64_t(videoMapped),meta,n+1==Frames?16384:8192);}
 FlGstVideoEvent end{};CHECK(fl_gst_session_receive_video_event(s,cfg.generation,10000,&end)==FL_GST_SESSION_READY&&end.kind==FL_GST_VIDEO_END&&end.afterFrames==Frames&&end.ptsNs==37000000+timeAt(Frames-1));CHECK(!gst_app_sink_try_pull_sample(GST_APP_SINK(audio.port),5*GST_SECOND)&&gst_app_sink_is_eos(GST_APP_SINK(audio.port)));terminal(audio.pipe);guint64 count=0;gint64 last=-1;CHECK(fl_gst_session_wait_video_eos(s,cfg.generation,10000,&count,&last)==FL_GST_SESSION_READY&&count==Frames&&last==int64_t(end.ptsNs));flFrame extra{};CHECK(flAcquireFrame(reader,&extra,0)==FL_TIMEOUT);CHECK(fl_gst_session_finish_local(s,FALSE,10000,nullptr));CloseHandle(held);CloseHandle(release);summary("16 distinct decoded digests match source PCM; held final read lease reverified before real completion; oracle readback explicit",true);}
 flClose(reader);g_object_unref(s);
}
static std::string quote(const std::string&s){CHECK(s.find('"')==std::string::npos);return "\""+s+"\"";}
static PROCESS_INFORMATION spawn(const char*childRole,HANDLE job){char exe[MAX_PATH];CHECK(GetModuleFileNameA(nullptr,exe,MAX_PATH));std::string command=quote(exe)+" "+quote(pluginPath)+" --out "+quote(directory)+" --role "+childRole;STARTUPINFOA si{};si.cb=sizeof si;PROCESS_INFORMATION pi{};CHECK(CreateProcessA(nullptr,command.data(),nullptr,nullptr,FALSE,CREATE_SUSPENDED,nullptr,nullptr,&si,&pi));if(!AssignProcessToJobObject(job,pi.hProcess)||ResumeThread(pi.hThread)==DWORD(-1)){CHECK(TerminateProcess(pi.hProcess,1));wait(pi.hProcess);CloseHandle(pi.hThread);CloseHandle(pi.hProcess);CHECK(false);}return pi;}
static void join(PROCESS_INFORMATION&p){wait(p.hProcess);DWORD rc=1;CHECK(GetExitCodeProcess(p.hProcess,&rc)&&rc==0);CloseHandle(p.hThread);CloseHandle(p.hProcess);}
static void relay(){HANDLE job=CreateJobObjectA(nullptr,nullptr);CHECK(job);JOBOBJECT_EXTENDED_LIMIT_INFORMATION limits{};limits.BasicLimitInformation.LimitFlags=JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE;CHECK(SetInformationJobObject(job,JobObjectExtendedLimitInformation,&limits,sizeof limits));auto sourceProcess=spawn("source",job),receiverProcess=spawn("receiver",job);auto c=caps();auto p=policy();auto*up=fl_gst_session_new(3);auto*down=fl_gst_session_new(3);flsample::LocalNativeRelaySetup setup{};GError*e=nullptr;CHECK(flsample::setupLocalNativeRelay(up,down,path("input").c_str(),path("output").c_str(),&c,&p,1,2,80,10000,10000,nullptr,&setup,&e));
 {using Compare=BOOL(WINAPI*)(HANDLE,HANDLE);auto compare=reinterpret_cast<Compare>(GetProcAddress(GetModuleHandleW(L"KernelBase.dll"),"CompareObjectHandles"));CHECK(compare);flsample::SessionNativeRelay video(up,down,setup.input,setup.output,[&](flImage*a,flImage*b){return compare(flImageSharedHandle(a),flImageSharedHandle(b))!=FALSE;});CHECK(video.initialize()==FL_OK);Audio input(up,false),output(down,true,true);flsample::SessionPcmRelay pcm(up,down,GST_APP_SINK(input.port),GST_APP_SRC(output.port));CHECK(pcm.initialize()==FL_GST_SESSION_READY);output.start();input.start();flsample::SessionRelaySupervisor supervisor(up,down);CHECK(supervisor.start()==FL_GST_SESSION_READY);auto held=event("held"),release=event("release"),retired=event("retired",false);CHECK(fl_gst_session_local_ready(down,TRUE,10000,nullptr)&&fl_gst_session_local_ready(up,FALSE,10000,nullptr));
 for(unsigned n=0;n<Frames;++n){flFrame frame{};CHECK(flAcquireFrame(setup.input,&frame,5000)==FL_OK&&frame.ptsNs==int64_t(37000000+timeAt(n)));flFrameMetadata meta{};CHECK(flGetFrameMetadata(setup.input,&frame,&meta)==FL_OK&&meta.version==FL_FRAME_METADATA_VERSION&&meta.flags==FL_FRAME_HAS_DURATION&&meta.dtsNs==0&&meta.durationNs==timeAt(1));CHECK(video.forward(frame)==FL_OK);const auto audioDeadline=g_get_monotonic_time()+5000000;while(pcm.blockCount()<n+1){CHECK(g_get_monotonic_time()<audioDeadline);auto r=pcm.forward(20);CHECK(r==FL_GST_SESSION_READY||r==FL_GST_SESSION_TIMEOUT);}if(n+1==Frames){wait(held);CHECK(video.collect()==FL_OK&&video.pending()==1);CHECK(video.collect()==FL_OK&&video.pending()==1);CHECK(SetEvent(release));}const auto deadline=g_get_monotonic_time()+5000000;while(video.pending()){CHECK(g_get_monotonic_time()<deadline&&supervisor.status()==FL_GST_SESSION_READY);CHECK(video.collect()==FL_OK);g_usleep(100);}CHECK(SetEvent(retired));}
 CHECK(video.forwardEvent(10000)==FL_GST_SESSION_READY&&video.videoEnded());terminal(input.pipe);CHECK(pcm.blockCount()==Frames&&pcm.frameCount()==25600&&pcm.byteCount()==102400);CHECK(pcm.finish(video,10000)==FL_GST_SESSION_READY);terminal(output.pipe);CHECK(video.finish()==FL_OK);supervisor.stop();CHECK(supervisor.status()==FL_GST_SESSION_READY);CHECK(fl_gst_session_finish_local(down,TRUE,10000,nullptr)&&fl_gst_session_finish_local(up,FALSE,10000,nullptr));CloseHandle(held);CloseHandle(release);CloseHandle(retired);summary("FAR4 source-relative and FAR5 reversed same-allocation snapshot; no video payload mapping; final held reader kept upstream pending",true);}
 join(receiverProcess);join(sourceProcess);flReleaseD3D11PoolSnapshot(setup.snapshot);flClose(setup.output);flClose(setup.input);g_object_unref(down);g_object_unref(up);CloseHandle(job);
}
int main(int argc,char**argv){CHECK(argc>=2);pluginPath=argv[1];for(int i=2;i<argc;++i){CHECK(i+1<argc);std::string key=argv[i],value=argv[++i];if(key=="--out")directory=value;else if(key=="--role")role=value;else CHECK(false);}CHECK(!directory.empty()&&(role=="relay"||role=="source"||role=="receiver"));directory=fs::absolute(directory).lexically_normal().string();if(role=="relay")CHECK(fs::create_directory(directory));FILE*log=nullptr;CHECK(freopen_s(&log,path((role+".stderr.log").c_str()).c_str(),"w",stderr)==0);setvbuf(stderr,nullptr,_IONBF,0);std::thread([]{Sleep(60000);fprintf(stderr,"owned decoder fixture watchdog expired\n");ExitProcess(2);}).detach();gst_init(&argc,&argv);GError*e=nullptr;auto*plugin=gst_plugin_load_file(pluginPath.c_str(),&e);CHECK(plugin&&!e);if(role=="source")source();else if(role=="receiver")receiver();else relay();gst_object_unref(plugin);return 0;}
